<?php
namespace App\Services\Trading;
class PositionManagementImpactSimulationService
{public function __construct(protected ?array $config=null){$this->config??=config('trading_position_management_plan');}
 public function simulate(array $ctx):array{$plan=$ctx['action_plan']??null;$pos=$ctx['managed_position']??($ctx['position']??null);$portfolio=$ctx['portfolio_context']??null;$agg=$ctx['exposure_aggregation']??null;$snap=$ctx['portfolio_position_snapshot']??null;$codes=[];$warnings=[];$blockers=[];$status='unavailable';$elig='action_plan_unavailable';$pimpact=['quantity_before'=>null,'quantity_proposed'=>null,'quantity_remaining'=>null,'reference_price'=>null,'gross_notional_before'=>null,'gross_notional_removed'=>null,'gross_notional_remaining'=>null,'reference_capital_at_risk_before'=>null,'reference_capital_at_risk_removed'=>null,'reference_capital_at_risk_remaining'=>null];$portfolioImpact=['status'=>'unavailable','portfolio_id'=>null,'gross_notional_before'=>null,'gross_notional_after_reference'=>null,'gross_capital_at_risk_before'=>null,'gross_capital_at_risk_after_reference'=>null,'position_count_before'=>null,'position_count_after_reference'=>null];
  if(!is_array($plan)||($plan['status']??null)!=='materialized_reference'){$this->add($codes,'POSITION_MANAGEMENT_IMPACT_ACTION_PLAN_REQUIRED',$blockers);} elseif(!is_array($pos)||($plan['position_id']??null)!==($pos['position_id']??null)){$status='blocked';$elig='identity_mismatch';$this->add($codes,'POSITION_MANAGEMENT_IMPACT_IDENTITY_MISMATCH',$blockers);} else {$q=$plan['quantity_plan'];$price=$plan['price_basis']['reference_price']??null;$pimpact=['quantity_before'=>$q['current_quantity'],'quantity_proposed'=>$q['proposed_quantity_reference'],'quantity_remaining'=>$q['remaining_quantity_reference'],'reference_price'=>$price,'gross_notional_before'=>$plan['position_impact_reference']['gross_notional_before'],'gross_notional_removed'=>$plan['position_impact_reference']['gross_notional_removed'],'gross_notional_remaining'=>$plan['position_impact_reference']['gross_notional_remaining'],'reference_capital_at_risk_before'=>null,'reference_capital_at_risk_removed'=>null,'reference_capital_at_risk_remaining'=>null];$status='simulated_reference';$elig='simulated_reference';$this->add($codes,'POSITION_MANAGEMENT_IMPACT_SIMULATED_REFERENCE');$this->add($codes,($plan['proposed_management_action']==='exit_position')?'POSITION_MANAGEMENT_IMPACT_FULL_EXIT_REFERENCE':'POSITION_MANAGEMENT_IMPACT_PARTIAL_REDUCTION_REFERENCE');
   if(is_array($snap)&&is_numeric($snap['capital_at_risk']??null)){$risk=(float)$snap['capital_at_risk'];$frac=(float)$q['proposed_quantity_reference']/(float)$q['current_quantity'];$pimpact['reference_capital_at_risk_before']=$risk;$pimpact['reference_capital_at_risk_removed']=round($risk*$frac,6);$pimpact['reference_capital_at_risk_remaining']=round($risk-$pimpact['reference_capital_at_risk_removed'],6);} else $this->add($codes,'POSITION_MANAGEMENT_IMPACT_CAPITAL_RISK_UNAVAILABLE',$warnings);
   if(is_array($portfolio)&&is_array($agg)&&is_array($snap)){$match=($portfolio['portfolio_id']??null)===($agg['portfolio_id']??null)&&($snap['position_id']??null)===($plan['position_id']??null)&&($snap['ticker']??null)===($pos['ticker']??null)&&(!isset($snap['currency'],$pos['currency'])||$snap['currency']===$pos['currency']); if(!$match){$portfolioImpact['status']='blocked';$status='partial';$this->add($codes,'POSITION_MANAGEMENT_IMPACT_POSITION_RECONCILIATION_FAILED',$blockers);} else {$before=(float)($agg['gross_notional']??$agg['gross_notional_before']??0);$portfolioImpact['status']='simulated_reference';$portfolioImpact['portfolio_id']=$portfolio['portfolio_id'];$portfolioImpact['gross_notional_before']=$before;$portfolioImpact['gross_notional_after_reference']=round($before-(float)$pimpact['gross_notional_removed'],6);$car=$agg['gross_capital_at_risk']??$agg['gross_capital_at_risk_before']??null;$portfolioImpact['gross_capital_at_risk_before']=$car;$portfolioImpact['gross_capital_at_risk_after_reference']=($car!==null&&$pimpact['reference_capital_at_risk_removed']!==null)?round((float)$car-$pimpact['reference_capital_at_risk_removed'],6):null;$count=$agg['position_count']??$agg['position_count_before']??null;$portfolioImpact['position_count_before']=$count;$portfolioImpact['position_count_after_reference']=$count!==null&&$plan['proposed_management_action']==='exit_position'&&($snap['position_count_policy']??null)==='full_removal'?max(0,$count-1):$count;}} else {if(!is_array($portfolio))$this->add($codes,'POSITION_MANAGEMENT_IMPACT_PORTFOLIO_CONTEXT_UNAVAILABLE',$warnings); if(!is_array($snap))$this->add($codes,'POSITION_MANAGEMENT_IMPACT_PORTFOLIO_SNAPSHOT_UNAVAILABLE',$warnings);} }
  foreach(['POSITION_MANAGEMENT_IMPACT_REALIZED_PNL_UNAVAILABLE','POSITION_MANAGEMENT_IMPACT_EXECUTION_COST_UNAVAILABLE','POSITION_MANAGEMENT_IMPACT_PORTFOLIO_APPROVAL_REQUIRED','POSITION_MANAGEMENT_IMPACT_NON_EXECUTABLE'] as $c)$this->add($codes,$c,$blockers);
  $r=['schema_version'=>$this->config['impact_schema_version'],'status'=>$status,'position_id'=>$plan['position_id']??null,'management_candidate_id'=>$plan['management_candidate_id']??null,'action_plan_id'=>$plan['action_plan_id']??null,'proposed_management_action'=>$plan['proposed_management_action']??null,'impact_scope'=>'reference_non_executable','eligibility'=>$elig,'position_impact'=>$pimpact,'portfolio_impact'=>$portfolioImpact,'cash_and_pnl'=>['gross_proceeds'=>null,'net_proceeds'=>null,'realized_pnl'=>null,'released_cash'=>null,'execution_cost'=>null],'approved'=>false,'reason_codes'=>$this->ordered($codes),'warnings'=>$this->ordered($warnings),'blockers'=>$this->ordered($blockers),'metadata'=>[]];$this->validateImpact($r);return $r;}
 public function validateImpact(array $r):void{if(($r['schema_version']??null)!==$this->config['impact_schema_version'])throw new \InvalidArgumentException('bad impact schema');if(!in_array($r['status'],['not_required','unavailable','partial','simulated_reference','blocked','invalid'],true))throw new \InvalidArgumentException('bad impact status');if(($r['approved']??null)!==false)throw new \InvalidArgumentException('impact approval forbidden');foreach($r['cash_and_pnl'] as $v)if($v!==null)throw new \InvalidArgumentException('cash pnl forbidden');}
 protected function add(&$c,$code,&$target=null):void{if(!in_array($code,$c,true))$c[]=$code;if(is_array($target)&&!in_array($code,$target,true))$target[]=$code;} protected function ordered($c):array{sort($c);return array_values(array_unique($c));}}
